#ifndef NCLGL_NCLGLUTILS_H
#define NCLGL_NCLGLUTILS_H

#define GLFW_INCLUDE_ES3
#include <GLFW/glfw3.h>

#include <stdlib.h>
#include <vector>
#include <string>
#include <algorithm>

class NCLGLUtils {
    public:
        NCLGLUtils();
        ~NCLGLUtils(void);

        static GLuint compileShader (GLenum type, std::string *source) {
            // Create shader object
            const GLchar* sourceString[1];
            GLint sourceStringLengths[1];

            sourceString[0] = source->c_str();
            sourceStringLengths[0] = source->length();
            GLuint shader = glCreateShader(type);

            if (shader == 0) {
                return 0;
            }

            // Assign and compile the source to the shader object
            glShaderSource(shader, 1, sourceString, sourceStringLengths);
            glCompileShader(shader);

            // Check if there were errors
            int infoLen = 0;
            glGetShaderiv( shader, GL_INFO_LOG_LENGTH, &infoLen );

            if (infoLen > 1) {
                char infoLog[infoLen];

                // And print them out
                glGetShaderInfoLog( shader, infoLen, NULL, infoLog );
                printf("%s\n", infoLog);

                free ( infoLog );
            }

            return shader;
        }

        static std::vector<std::string> split(std::string str, std::string delimiter) {
            std::vector<std::string> out;

            size_t pos = 0;
            std::string token;
            while ((pos = str.find(delimiter)) != std::string::npos) {
                token = str.substr(0, pos);
                out.push_back(token);
                str.erase(0, pos + delimiter.length());
            }
            out.push_back(str);

            return out;
        }

    static int fn(int ch) {
        return !std::isspace(ch);
    }
    static inline void ltrim(std::string &s) {
        s.erase(s.begin(), std::find_if(s.begin(), s.end(), NCLGLUtils::fn));
    }
    static inline void rtrim(std::string &s) {
        s.erase(std::find_if(s.rbegin(), s.rend(), NCLGLUtils::fn).base(), s.end());
    }
    static std::string trim(std::string &s) {
        ltrim(s);
        rtrim(s);
        return s;
    }

    private:
        int dd;
};

#endif //NCLGL_NCLGLUTILS_H